/**
 * Private file storage for member photos and the gym logo (backend design
 * §12), kept in PostgreSQL. Images are re-encoded and small, so the database
 * is a good home on serverless platforms without a persistent disk: files are
 * written and removed in the same transaction as the record that points at
 * them, and every database backup includes them. Files are served only through
 * authenticated API routes; keys are generated by the server.
 */

import { randomUUID } from "node:crypto";
import type { Db, Tx } from "../db";

const KEY_RE = /^(members|logo)\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(jpg|png)$/;
type ContentType = "image/jpeg" | "image/png";

export interface StoredFile {
  contentType: ContentType;
  data: Buffer;
}

function checkKey(key: string): string {
  if (!KEY_RE.test(key)) throw new Error(`Invalid storage key: ${key}`);
  return key;
}

export class FileStorage {
  /** New key for an object owned by `ownerId` (a member id, or the logo slot). */
  newKey(kind: "members" | "logo", ownerId: string, extension: "jpg" | "png"): string {
    return `${kind}/${ownerId}/${randomUUID()}.${extension}`;
  }

  async put(db: Db | Tx, key: string, file: StoredFile): Promise<void> {
    await db
      .insertInto("stored_files")
      .values({ key: checkKey(key), content_type: file.contentType, data: file.data })
      .execute();
  }

  async get(db: Db | Tx, key: string): Promise<StoredFile | null> {
    const row = await db
      .selectFrom("stored_files")
      .select(["content_type", "data"])
      .where("key", "=", checkKey(key))
      .executeTakeFirst();
    return row ? { contentType: row.content_type, data: row.data } : null;
  }

  /** Removes a file once nothing points at it (call after clearing the reference, in the same transaction). */
  async delete(db: Db | Tx, key: string): Promise<void> {
    await db.deleteFrom("stored_files").where("key", "=", checkKey(key)).execute();
  }
}
